def maxDistance(grid):
    import collections

    n = len(grid)
    queue = collections.deque()

    # Initialize queue with all land cells
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                queue.append((i, j))

    # If there are no land cells or no water cells, return -1
    if not queue or len(queue) == n * n:
        return -1

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    max_dist = 0

    while queue:
        size = len(queue)
        for _ in range(size):
            r, c = queue.popleft()

            for dr, dc in directions:
                nr, nc = r + dr, c + dc

                if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] == 0:
                    grid[nr][nc] = 1  # Mark as visited
                    queue.append((nr, nc))

        max_dist += 1

    return max_dist - 1 if max_dist > 0 else -1
